hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", 1)

-- ── Entrée ──

hl.config({
    input = {
        kb_layout = "us",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
        },
    },
})

-- ── Général ──

hl.config({
    general = {
        gaps_in = 4,
        gaps_out = 8,
        border_size = 1,
        layout = "dwindle",
        col = {
            active_border = "rgba(c8b89aee)",
            inactive_border = "rgba(1a1814aa)",
        },
    },
})

-- ── Décoration ──

hl.config({
    decoration = {
        rounding = 0,
        blur = {
            enabled = false,
        },
        shadow = {
            enabled = false,
        },
    },
})

-- ── Animations ──

hl.config({
    animations = {
        enabled = true,
    },
})

-- ── Layout dwindle ──

hl.config({
    dwindle = {
        preserve_split = true,
    },
})

-- ── Layout master ──

hl.config({
    master = {
        new_status = "master",
        mfact = 0.55,
    },
})

-- ── Règles fenêtres Quickshell ──

hl.window_rule({
